-- Дахин ажиллуулахад аюулгүй (upsert).
begin;
insert into public.mock_tests (id, hsk_level, title, total_questions, time_limit_min, has_writing, sections, is_active)
values ('M62602', 6, 'HSK 6 · HSK 3.0 загвар шалгалт №2 (全真模拟)', 82, 115, true, '[{"skill": "listening", "audio_url": "/mock-tests/m62602/listening.mp3", "time_min": 30, "parts": [{"part": 1, "range": [1, 8], "q_type": "choice", "desc": "Богино мэдээ → асуулт (сонголт)"}, {"part": 2, "range": [9, 28], "q_type": "choice", "desc": "Эх сонсоод → асуулт (сонголт)"}, {"part": 3, "range": [29, 40], "q_type": "choice", "desc": "Ярилцлага → асуулт (сонголт)"}]}, {"skill": "reading", "audio_url": null, "time_min": 40, "parts": [{"part": 1, "range": [41, 50], "q_type": "choice", "desc": "Үг сонгон нөхөх"}, {"part": 2, "range": [51, 60], "q_type": "choice", "desc": "Өгүүлбэр сонгон нөхөх"}, {"part": 3, "range": [61, 80], "q_type": "choice", "desc": "Эх унших → асуулт"}]}, {"skill": "writing", "audio_url": null, "time_min": 45, "parts": [{"part": 1, "range": [81, 81], "q_type": "essay", "desc": "Практик өгүүлэл"}, {"part": 2, "range": [82, 82], "q_type": "essay", "desc": "Санал бодлын өгүүлэл"}]}]'::jsonb, true)
on conflict (id) do update set hsk_level=excluded.hsk_level, title=excluded.title, total_questions=excluded.total_questions,
