insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M62602','listening',1,1,'choice','','[{"key": "A", "text": "数字化时代已经不需要阅读"}, {"key": "B", "text": "民众素质的提高不依赖阅读"}, {"key": "C", "text": "深度阅读有助于增强思考力"}, {"key": "D", "text": "简单阅读比深度阅读更有用"}]'::jsonb,'C','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх сурвалж «гүнзгий уншлагаар сэтгэх чадвараа дээшлүүлэх хэрэгтэй» гэж тодорхой хэлсэн тул C зөв.',42.41,82.45,'在数字化时代，阅读不仅能丰富知识，也是提高民众素质的重要途径。面对大量信息，我们要保持清醒的头脑，不能只满足于简单的阅读，而要通过深度阅读来增强思考能力。坚持读好书，有助于大家在处理复杂问题时做出正确判断，从而实现自我提升。','{"why": "Эх сурвалж «гүнзгий уншлагаар сэтгэх чадвараа дээшлүүлэх хэрэгтэй» гэж тодорхой хэлсэн тул C зөв.", "key": "通过深度阅读来增强思考能力", "keyMn": "Гүнзгий уншлагаар сэтгэх чадвараа дээшлүүлнэ", "wrong": {"A": "Дижитал эрин үед ч унших нь «ард түмний боловсролыг дээшлүүлэх чухал зам» гэсэн тул хэрэггүй биш.", "B": "Унших нь боловсролыг дээшлүүлэх зам гэсэн, өөрөөр хэлбэл хоорондоо холбоотой.", "D": "Эх «зүгээр л өнгөц уншиж сэтгэл ханаж болохгүй» гэсэн, өнгөц унших нь илүү гэсэн зүйл алга."}, "words": [{"zh": "深度阅读", "pinyin": "shēndù yuèdú", "mn": "гүнзгий уншлага"}, {"zh": "思考能力", "pinyin": "sīkǎo nénglì", "mn": "сэтгэх чадвар"}, {"zh": "素质", "pinyin": "sùzhì", "mn": "чанар, боловсрол"}, {"zh": "途径", "pinyin": "tújìng", "mn": "зам, арга"}], "transcript": [{"zh": "在数字化时代，阅读不仅能丰富知识，也是提高民众素质的重要途径。面对大量信息，我们要保持清醒的头脑，不能只满足于简单的阅读，而要通过深度阅读来增强思考能力。坚持读好书，有助于大家在处理复杂问题时做出正确判断，从而实现自我提升。", "mn": "Дижитал эрин үед унших нь мэдлэгийг баяжуулаад зогсохгүй, ард түмний боловсролыг дээшлүүлэх чухал зам юм. Их хэмжээний мэдээлэлтэй тулгарахдаа бид толгойгоо цэвэр байлгаж, зүгээр л өнгөц уншиж сэтгэл ханаж болохгүй, гүнзгий уншлагаар сэтгэх чадвараа дээшлүүлэх хэрэгтэй. Сайн ном байнга унших нь төвөгтэй асуудлыг шийдэхэд зөв дүгнэлт гаргахад тусалж, улмаар өөрийгөө хөгжүүлэхэд хүргэнэ."}]}'::jsonb),
('M62602','listening',1,2,'choice','','[{"key": "A", "text": "办证流程更加方便"}, {"key": "B", "text": "工作人员在线指导"}, {"key": "C", "text": "业务仍须多次办理"}, {"key": "D", "text": "办理业务无须到场"}]'::jsonb,'A','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Олон ажлыг «нэг цонхоор» нэг дор хийж, явж ирэх хугацааг хэмнэсэн тул журам илүү хялбар болсон. Хариу A.',82.75,122.06,'近日，在常州市工作的外籍人士办理工作许可和居留许可时，可通过“一站式”服务窗口同时办理社保、医保以及手机卡、银行卡等业务。工作人员现场提示办理流程，并给予指导。该服务将多项业务集中办理，减少了办事的往返时间，为外籍人员在常州工作和生活提供了相应保障。','{"why": "Олон ажлыг «нэг цонхоор» нэг дор хийж, явж ирэх хугацааг хэмнэсэн тул журам илүү хялбар болсон. Хариу A.", "key": "减少了办事的往返时间", "keyMn": "Ажлаар явж ирэх хугацааг хэмнэсэн", "wrong": {"B": "Ажилтан «газар дээр нь» заавар өгдөг, онлайн биш.", "C": "«Нэг дор» шийддэг тул олон удаа очих шаардлагагүй.", "D": "«Газар дээр нь» тайлбарласан гэдэг нь биечлэн очдог гэсэн үг."}, "words": [{"zh": "一站式", "pinyin": "yízhànshì", "mn": "нэг цонхны (нэг дор)"}, {"zh": "居留许可", "pinyin": "jūliú xǔkě", "mn": "оршин суух зөвшөөрөл"}, {"zh": "现场", "pinyin": "xiànchǎng", "mn": "газар дээр нь"}, {"zh": "往返", "pinyin": "wǎngfǎn", "mn": "явж ирэх"}], "transcript": [{"zh": "近日，在常州市工作的外籍人士办理工作许可和居留许可时，可通过“一站式”服务窗口同时办理社保、医保以及手机卡、银行卡等业务。工作人员现场提示办理流程，并给予指导。该服务将多项业务集中办理，减少了办事的往返时间，为外籍人员在常州工作和生活提供了相应保障。", "mn": "Саяхан Чанчжоу хотод ажилладаг гадаад иргэд ажлын зөвшөөрөл, оршин суух зөвшөөрлөө авахдаа «нэг цонхны» үйлчилгээгээр нийгмийн даатгал, эрүүл мэндийн даатгал, гар утасны сим карт, банкны карт зэрэг ажлыг нэг дор хийлгэж болох болсон. Ажилтнууд газар дээр нь явцыг тайлбарлаж, зааварчилгаа өгдөг. Энэ үйлчилгээ олон ажлыг нэг дор цэглэснээр явж ирэх хугацааг хэмнэж, гадаад хүмүүсийн ажил амьдралд дэмжлэг болж байна."}]}'::jsonb),
('M62602','listening',1,3,'choice','','[{"key": "A", "text": "让顾客打包剩菜"}, {"key": "B", "text": "要求顾客多点菜"}, {"key": "C", "text": "限制顾客带酒水"}, {"key": "D", "text": "鼓励顾客按需点菜"}]'::jsonb,'D','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Хоолны газрууд «хэрэгцээндээ тохируулан захиалахад» чиглүүлж байгаа тул D зөв.',122.36,163.66,'针对不同顾客的实际需求，部分餐饮店推出“小份菜”和按需取菜的方式，引导顾客根据食量合理点菜，减少不必要的浪费。同时，通过宣传文明用餐理念，提醒顾客避免出现大量剩菜的情况。这些做法不仅改善了整体用餐体验，也有助于顾客逐步形成理性消费的饮食习惯。','{"why": "Хоолны газрууд «хэрэгцээндээ тохируулан захиалахад» чиглүүлж байгаа тул D зөв.", "key": "引导顾客根据食量合理点菜", "keyMn": "Хүн бүрийг идэх хэмжээгээрээ зохистой захиалахад чиглүүлнэ", "wrong": {"A": "Үлдсэнийг боож авах тухай яриагүй, харин хоол үлдээхээс сэргийлнэ.", "B": "Дэмий үрэлгийг багасгахыг хэлсэн, илүү захиалуулах нь эсрэг утга.", "C": "Ундаа, архины тухай огт яриагүй."}, "words": [{"zh": "按需", "pinyin": "ànxū", "mn": "хэрэгцээндээ тааруулан"}, {"zh": "浪费", "pinyin": "làngfèi", "mn": "дэмий үрэлгэх"}, {"zh": "剩菜", "pinyin": "shèngcài", "mn": "үлдсэн хоол"}, {"zh": "理性消费", "pinyin": "lǐxìng xiāofèi", "mn": "оновчтой хэрэглээ"}], "transcript": [{"zh": "针对不同顾客的实际需求，部分餐饮店推出“小份菜”和按需取菜的方式，引导顾客根据食量合理点菜，减少不必要的浪费。同时，通过宣传文明用餐理念，提醒顾客避免出现大量剩菜的情况。这些做法不仅改善了整体用餐体验，也有助于顾客逐步形成理性消费的饮食习惯。", "mn": "Үйлчлүүлэгчдийн бодит хэрэгцээнд тулгуурлан зарим хоолны газар «жижиг порц» болон хэрэгтэй хэмжээгээр нь авдаг хэлбэр нэвтрүүлж, хүн бүрийг идэх хэмжээндээ тохируулан захиалахад чиглүүлж, дэмий үрэлгийг багасгаж байна. Мөн соёлтой хооллох санааг сурталчилж, хоол их үлдээхээс зайлсхийхийг сануулдаг. Эдгээр арга нь хоолны орчныг сайжруулаад зогсохгүй, хэрэглэгчид оновчтой хэрэглээний хоолны зуршил аажмаар төлөвшихөд тусалдаг."}]}'::jsonb),
('M62602','listening',1,4,'choice','','[{"key": "A", "text": "野外出行不存在风险"}, {"key": "B", "text": "出发前无须规划路线"}, {"key": "C", "text": "出行前要做好充分准备"}, {"key": "D", "text": "迷路后应继续沿路前行"}]'::jsonb,'C','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Мэргэжилтэн «гарахаасаа өмнө зам төлөвлөж, ус хоол, анхны тусламжийн хэрэгсэл бэлд» гэсэн тул C зөв.',163.96,204.25,'暑期野外出行增多，但环境复杂、风险较高。专家提醒，出发前要做好路线规划，提前了解天气和地形情况，并准备充足的饮用水、食物和急救用品。如出现手机信号中断或迷路等紧急情况，可前往较高位置寻找明显标志，并利用求救哨或手电发出信号，等待救援。','{"why": "Мэргэжилтэн «гарахаасаа өмнө зам төлөвлөж, ус хоол, анхны тусламжийн хэрэгсэл бэлд» гэсэн тул C зөв.", "key": "出发前要做好路线规划，……准备充足的饮用水、食物和急救用品", "keyMn": "Гарахаасаа өмнө замаа төлөвлөж, ус хоол, анхны тусламжийн хэрэгсэл бэлд", "wrong": {"A": "Эхэнд «орчин төвөгтэй, эрсдэл өндөр» гэсэн.", "B": "«Зам төлөвлөх» шаардлагатай гэж хэлсэн.", "D": "Төөрвөл өндөр газар гарч дохио өгөөд хүлээ гэсэн, цааш алхах гэсэн биш."}, "words": [{"zh": "野外", "pinyin": "yěwài", "mn": "байгаль, хээр"}, {"zh": "风险", "pinyin": "fēngxiǎn", "mn": "эрсдэл"}, {"zh": "急救用品", "pinyin": "jíjiù yòngpǐn", "mn": "анхны тусламжийн хэрэгсэл"}, {"zh": "求救", "pinyin": "qiújiù", "mn": "тусламж дуудах"}], "transcript": [{"zh": "暑期野外出行增多，但环境复杂、风险较高。专家提醒，出发前要做好路线规划，提前了解天气和地形情况，并准备充足的饮用水、食物和急救用品。如出现手机信号中断或迷路等紧急情况，可前往较高位置寻找明显标志，并利用求救哨或手电发出信号，等待救援。", "mn": "Зуны амралтаар байгальд гарах хүн нэмэгдэж байгаа ч орчин нь төвөгтэй, эрсдэл өндөр. Мэргэжилтнүүд гарахаасаа өмнө замаа сайн төлөвлөж, цаг агаар, газрын хэлбэрийг урьдчилан мэдэж, хангалттай ундны ус, хоол хүнс, анхны тусламжийн хэрэгсэл бэлдэхийг сануулж байна. Гар утасны сүлжээ тасарсан, төөрсөн зэрэг яаралтай үед өндөр газар гарч тод тэмдэг хайж, аврах шүгэл эсвэл гар чийдэнгээр дохио өгөөд аврагчдыг хүлээх хэрэгтэй."}]}'::jsonb),
('M62602','listening',1,5,'choice','','[{"key": "A", "text": "健康保障体系太复杂"}, {"key": "B", "text": "关注身体异常很重要"}, {"key": "C", "text": "身体出现小毛病不用管"}, {"key": "D", "text": "健康问题多由环境决定"}]'::jsonb,'B','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «биеийн өдөр тутмын өөрчлөлтийг анхаар, цаг алдалгүй зөвлөлд» гэж онцолсон тул B зөв.',204.55,246.0,'健康管理离不开正确认知，然而不少人常常忽略身体发出的信号，容易在关键环节拖延应对。长期面对压力、不规律生活节奏等，会导致身体出现异常症状。建立科学健康观念，关注身体日常变化，及时咨询专业人员，有助于构建稳定的健康保障体系，从而有效降低风险，改善生活质量。','{"why": "Эх «биеийн өдөр тутмын өөрчлөлтийг анхаар, цаг алдалгүй зөвлөлд» гэж онцолсон тул B зөв.", "key": "关注身体日常变化，及时咨询专业人员", "keyMn": "Биеийн өдөр тутмын өөрчлөлтийг анхаарч, мэргэжлийн хүнтэй цаг алдалгүй зөвлөлд", "wrong": {"A": "Эрүүл мэндийн хамгаалалтын тогтолцоо хэр төвөгтэй гэдгийг яриагүй.", "C": "Биеийн дохиог үл тоовол арга хэмжээгээ хойшлуулж, эрсдэл нэмэгдэнэ гэсэн.", "D": "Стресс, дэглэмгүй амьдрал зэрэг хувь хүний хүчин зүйлийг нэрлэсэн, орчин гэсэн биш."}, "words": [{"zh": "信号", "pinyin": "xìnhào", "mn": "дохио"}, {"zh": "拖延", "pinyin": "tuōyán", "mn": "хойшлуулах"}, {"zh": "异常", "pinyin": "yìcháng", "mn": "хэвийн бус"}, {"zh": "咨询", "pinyin": "zīxún", "mn": "зөвлөлдөх"}], "transcript": [{"zh": "健康管理离不开正确认知，然而不少人常常忽略身体发出的信号，容易在关键环节拖延应对。长期面对压力、不规律生活节奏等，会导致身体出现异常症状。建立科学健康观念，关注身体日常变化，及时咨询专业人员，有助于构建稳定的健康保障体系，从而有效降低风险，改善生活质量。", "mn": "Эрүүл мэндээ зөв удирдахад зөв ойлголт чухал. Гэвч олон хүн биеийн өгч буй дохиог үл тоож, чухал үед арга хэмжээгээ хойшлуулдаг. Удаан хугацаанд стресстэй, дэглэмгүй амьдрах нь биед хэвийн бус шинж тэмдэг үүсгэдэг. Шинжлэх ухааны эрүүл мэндийн үзэл баримтлал тогтоож, биеийн өдөр тутмын өөрчлөлтийг анхаарч, мэргэжлийн хүнтэй цаг алдалгүй зөвлөлдөх нь тогтвортой эрүүл мэндийн хамгаалалтын тогтолцоог бүрдүүлж, эрсдэлийг үр дүнтэй бууруулж, амьдралын чанарыг сайжруулахад тусална."}]}'::jsonb),
('M62602','listening',1,6,'choice','','[{"key": "A", "text": "物业便民服务安排周到"}, {"key": "B", "text": "社区活动每天都很密集"}, {"key": "C", "text": "居民仅靠公告获取信息"}, {"key": "D", "text": "便民活动是指家电维修"}]'::jsonb,'A','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх засвар, даралт хэмжих, үс засах зэрэг олон үйлчилгээ санал болгосон тул үйлчилгээ нь сайн төлөвлөгдсөн гэсэн A зөв.',246.3,287.44,'近日，上海普陀区开展“物业便民服务周”活动，物业联合社区提供家电维修、测血压、理发、健康咨询等服务，并组织文化互动、法律咨询、家电上门维护等活动。居民通过微信群或公告获取信息，活动不仅改善了社区环境，提升了生活便利度，也促进了邻里交流，增强了居民幸福感。','{"why": "Эх засвар, даралт хэмжих, үс засах зэрэг олон үйлчилгээ санал болгосон тул үйлчилгээ нь сайн төлөвлөгдсөн гэсэн A зөв.", "key": "提供家电维修、测血压、理发、健康咨询等服务", "keyMn": "Цахилгаан хэрэгсэл засах, даралт хэмжих, үс засах, эрүүл мэндийн зөвлөгөө өгнө", "wrong": {"B": "«Үйлчилгээний долоо хоног» гэсэн ч өдөр бүр өтгөн гэж яриагүй.", "C": "Оршин суугчид «вичат групп болон зарын самбар» гэсэн хоёр сувгаар мэдээлэл авна.", "D": "Засвараас гадна үс засах, даралт хэмжих зэрэг олон үйлчилгээ бий."}, "words": [{"zh": "物业", "pinyin": "wùyè", "mn": "орон сууцны удирдлага"}, {"zh": "便民", "pinyin": "biànmín", "mn": "иргэдэд тохиромжтой"}, {"zh": "邻里", "pinyin": "línlǐ", "mn": "хөршүүд"}, {"zh": "公告", "pinyin": "gōnggào", "mn": "зар"}], "transcript": [{"zh": "近日，上海普陀区开展“物业便民服务周”活动，物业联合社区提供家电维修、测血压、理发、健康咨询等服务，并组织文化互动、法律咨询、家电上门维护等活动。居民通过微信群或公告获取信息，活动不仅改善了社区环境，提升了生活便利度，也促进了邻里交流，增强了居民幸福感。", "mn": "Саяхан Шанхайн Пүтүө дүүрэгт «Орон сууцны үйлчилгээний долоо хоног» боллоо. Орон сууцны удирдлага, хороолол хамтран гэр ахуйн цахилгаан хэрэгсэл засах, даралт хэмжих, үс засах, эрүүл мэндийн зөвлөгөө өгөх зэрэг үйлчилгээ үзүүлж, соёлын тоглоом наадам, хууль зүйн зөвлөгөө, гэрт нь очиж засвар хийх үйл ажиллагаа зохион байгууллаа. Оршин суугчид вичат групп болон зарын самбараас мэдээлэл авдаг. Энэ арга хэмжээ хорооллын орчныг сайжруулж, амьдралыг эвтэйхэн болгож, хөршүүдийн харилцааг дэмжиж, оршин суугчдын аз жаргалыг нэмэгдүүлсэн."}]}'::jsonb),
('M62602','listening',1,7,'choice','','[{"key": "A", "text": "机械练习是深度学习的关键"}, {"key": "B", "text": "家长普遍支持这次考试改革"}, {"key": "C", "text": "改革以后会增加考试的频率"}, {"key": "D", "text": "挑战性任务有助于能力提升"}]'::jsonb,'D','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эцэст нь «сорилттой суралцах даалгавар л чадварыг дээшлүүлэх түлхүүр» гэсэн тул D зөв.',287.74,332.14,'近年来，教育部门推动学校减少日常考试次数，将重心从频繁检测转向深度学习与研究上。部分家长担忧考试减少会影响学习效果，专家指出，教育改革的核心在于提升学生解决复杂问题的能力，而非依赖机械练习。高质量的课堂与富有挑战性的学习任务，才是提高学生能力的关键。','{"why": "Эцэст нь «сорилттой суралцах даалгавар л чадварыг дээшлүүлэх түлхүүр» гэсэн тул D зөв.", "key": "富有挑战性的学习任务，才是提高学生能力的关键", "keyMn": "Сорилттой суралцах даалгавар л чадварыг дээшлүүлэх түлхүүр", "wrong": {"A": "Мэргэжилтэн «механик дадлагад найдах биш» гэсэн, эсрэг утга.", "B": "«Зарим эцэг эх» санаа зовсон гэсэн, ихэнх нь дэмжсэн гэсэн биш.", "C": "Эх «шалгалтын тоог цөөлөх» гэсэн, нэмэх биш."}, "words": [{"zh": "考试改革", "pinyin": "kǎoshì gǎigé", "mn": "шалгалтын шинэчлэл"}, {"zh": "机械练习", "pinyin": "jīxiè liànxí", "mn": "механик дадлага"}, {"zh": "挑战性", "pinyin": "tiǎozhànxìng", "mn": "сорилттой"}, {"zh": "关键", "pinyin": "guānjiàn", "mn": "түлхүүр"}], "transcript": [{"zh": "近年来，教育部门推动学校减少日常考试次数，将重心从频繁检测转向深度学习与研究上。部分家长担忧考试减少会影响学习效果，专家指出，教育改革的核心在于提升学生解决复杂问题的能力，而非依赖机械练习。高质量的课堂与富有挑战性的学习任务，才是提高学生能力的关键。", "mn": "Сүүлийн жилүүдэд боловсролын байгууллага сургуулиудыг өдөр тутмын шалгалтын тоог цөөлөхийг түлхэж, хүнд хэмжээг байнгын шалгалтаас гүнзгийрүүлсэн суралцахуй, судалгаа руу шилжүүлж байна. Зарим эцэг эх шалгалт цөөрвөл сурлагад муугаар нөлөөлнө гэж санаа зовж байна. Мэргэжилтнүүд боловсролын шинэчлэлийн цөм нь оюутнуудын төвөгтэй асуудал шийдэх чадварыг дээшлүүлэх явдал мөн, механик дадлага биш гэж хэлж байна. Өндөр чанартай хичээл болон сорилттой суралцах даалгавар л чадварыг дээшлүүлэх түлхүүр юм."}]}'::jsonb),
('M62602','listening',1,8,'choice','','[{"key": "A", "text": "违法记录须到窗口查询"}, {"key": "B", "text": "可用手机处理交通违法"}, {"key": "C", "text": "必须携带材料现场处理"}, {"key": "D", "text": "无法在线查询处罚进度"}]'::jsonb,'B','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эх «гар утасны аппаар онлайнаар шалгаж, хүсэлт гаргаж, торгуулийг шийдвэрлэж болно» гэсэн тул B зөв.',332.44,385.34,'公安部门规定，收到交通违法提示后，相关人员可通过手机应用在线查询、申请并处理处罚。该方式不仅便捷，还能实时查询办理进度，了解提示信息，极大提升了办事效率。对于线上办理过程中遇到困难或有疑问的群众，可选择携带相关材料前往服务窗口进行咨询或说明。','{"why": "Эх «гар утасны аппаар онлайнаар шалгаж, хүсэлт гаргаж, торгуулийг шийдвэрлэж болно» гэсэн тул B зөв.", "key": "可通过手机应用在线查询、申请并处理处罚", "keyMn": "Гар утасны аппаар онлайнаар шалгаж, хүсэлт гаргаж, торгуулийг шийдвэрлэнэ", "wrong": {"A": "Онлайнаар шалгана; цонх бол хүндрэлтэй хүмүүст зориулсан нэмэлт арга.", "C": "Материал бариад очих нь зөвхөн бэрхшээл тулгарсан үед.", "D": "Эх «бодит цагт явцыг шалгана» гэсэн."}, "words": [{"zh": "交通违法", "pinyin": "jiāotōng wéifǎ", "mn": "замын хөдөлгөөний зөрчил"}, {"zh": "处罚", "pinyin": "chǔfá", "mn": "торгууль, шийтгэл"}, {"zh": "实时", "pinyin": "shíshí", "mn": "бодит цагт"}, {"zh": "窗口", "pinyin": "chuāngkǒu", "mn": "үйлчилгээний цонх"}], "transcript": [{"zh": "公安部门规定，收到交通违法提示后，相关人员可通过手机应用在线查询、申请并处理处罚。该方式不仅便捷，还能实时查询办理进度，了解提示信息，极大提升了办事效率。对于线上办理过程中遇到困难或有疑问的群众，可选择携带相关材料前往服务窗口进行咨询或说明。", "mn": "Цагдаагийн байгууллагын журмаар, замын хөдөлгөөний зөрчлийн мэдэгдэл авсан хүн гар утасны аппаар онлайнаар шалгаж, хүсэлт гаргаж, торгуулийг шийдвэрлэж болно. Энэ арга хялбар төдийгүй, явцыг бодит цагт харж, мэдэгдлийг мэдэж болдог тул ажлын үр ашгийг маш их дээшлүүлсэн. Онлайнаар шийдвэрлэх явцад бэрхшээл тулгарсан, эсвэл асуулт гарсан иргэд холбогдох материалаа бариад үйлчилгээний цонхонд очиж зөвлөгөө авах, тайлбарлах боломжтой."}]}'::jsonb),
('M62602','listening',2,9,'choice','','[{"key": "A", "text": "取代了传统的人际沟通"}, {"key": "B", "text": "学生数据需要全部公开"}, {"key": "C", "text": "推动了管理理念的转变"}, {"key": "D", "text": "在线办理流程非常复杂"}]'::jsonb,'C','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'Эхний хэсэгт «үр ашгийг дээшлүүлээд зогсохгүй, удирдлагын үзэл баримтлалыг өөрчлөхөд түлхэц болсон» гэсэн тул C.',385.64,554.88,'随着信息技术的飞速发展，“云端管理”已逐渐融入高校日常管理的方方面面。许多学校通过建设智慧校园平台，实现学生事务“一站式”在线办理。这种以数字化为支撑的管理方式，不仅显著提升了办事效率，也推动了高校管理理念的转变。
以部分高校推出的“学生画像”系统为例，学校通过汇集学生的学习表现、借书记录、食堂消费等数据，实时了解学生在校的整体状态。借助数据分析，学校能够精准识别出生活困难或情绪焦虑的学生，并及时给予关怀。这一机制改变了以往问题出现后再处理的被动局面，使学生管理逐步转向主动服务。
与此同时，数字人主播、知识地图等应用不断为校园活动注入新动力，提升了信息传递和活动组织的效果。在推进数字化建设的过程中，高校也在探索技术与情感融合的方式，既发挥数字技术的优势，又避免让数据取代人与人之间面对面的沟通。只有将技术手段与关爱精神有机融合，数字化管理才能真正服务学生成长。
问：关于智慧校园平台，下列哪一项正确？','{"why": "Эхний хэсэгт «үр ашгийг дээшлүүлээд зогсохгүй, удирдлагын үзэл баримтлалыг өөрчлөхөд түлхэц болсон» гэсэн тул C.", "key": "也推动了高校管理理念的转变", "keyMn": "Их дээд сургуулийн удирдлагын үзэл баримтлалыг өөрчлөхөд түлхэц болсон", "wrong": {"A": "Эх «өгөгдөл хүн хоорондын нүүр тулсан харилцааг орлохоос зайлсхий» гэсэн.", "B": "Өгөгдлийг оюутны байдлыг мэдэхэд ашигладаг, олон нийтэд нээнэ гэсэн зүйл алга.", "D": "«Нэг цонхны» онлайн журам үр ашгийг дээшлүүлсэн, төвөгтэй биш."}, "words": [{"zh": "智慧校园", "pinyin": "zhìhuì xiàoyuán", "mn": "ухаалаг кампус"}, {"zh": "管理理念", "pinyin": "guǎnlǐ lǐniàn", "mn": "удирдлагын үзэл баримтлал"}, {"zh": "一站式", "pinyin": "yízhànshì", "mn": "нэг цонхны"}, {"zh": "显著", "pinyin": "xiǎnzhù", "mn": "мэдэгдэхүйц"}], "transcript": [{"zh": "随着信息技术的飞速发展，“云端管理”已逐渐融入高校日常管理的方方面面。许多学校通过建设智慧校园平台，实现学生事务“一站式”在线办理。这种以数字化为支撑的管理方式，不仅显著提升了办事效率，也推动了高校管理理念的转变。", "mn": "Мэдээллийн технологи хурдацтай хөгжихийн хэрээр «үүлэн удирдлага» их дээд сургуулийн өдөр тутмын удирдлагын бүх талд аажмаар нэвтэрч байна. Олон сургууль ухаалаг кампусын платформ байгуулж, оюутны хэрэг явдлыг «нэг цонхоор» онлайнаар шийдэж байна. Дижитал дэмжлэгтэй ийм удирдлага нь ажлын үр ашгийг мэдэгдэхүйц дээшлүүлээд зогсохгүй, их дээд сургуулийн удирдлагын үзэл баримтлалыг өөрчлөхөд түлхэц болсон."}, {"zh": "以部分高校推出的“学生画像”系统为例，学校通过汇集学生的学习表现、借书记录、食堂消费等数据，实时了解学生在校的整体状态。借助数据分析，学校能够精准识别出生活困难或情绪焦虑的学生，并及时给予关怀。这一机制改变了以往问题出现后再处理的被动局面，使学生管理逐步转向主动服务。", "mn": "Зарим их дээд сургуулийн нэвтрүүлсэн «оюутны хөрөг» системийг жишээ болгоё. Сургууль оюутны сурлагын үзүүлэлт, ном зээлсэн түүх, хоолны газрын зарцуулалт зэрэг өгөгдлийг цуглуулж, оюутнуудын сургууль дахь ерөнхий байдлыг бодит цагт мэддэг. Өгөгдлийн шинжилгээгээр амьдралын хүндрэлтэй, сэтгэлийн түгшүүртэй оюутныг нарийн олж, цаг алдалгүй халамжилдаг. Энэ механизм өмнө нь асуудал гарсны дараа л шийддэг байсан идэвхгүй байдлыг өөрчилж, оюутны удирдлагыг аажмаар идэвхтэй үйлчилгээ рүү шилжүүлжээ."}, {"zh": "与此同时，数字人主播、知识地图等应用不断为校园活动注入新动力，提升了信息传递和活动组织的效果。在推进数字化建设的过程中，高校也在探索技术与情感融合的方式，既发挥数字技术的优势，又避免让数据取代人与人之间面对面的沟通。只有将技术手段与关爱精神有机融合，数字化管理才能真正服务学生成长。", "mn": "Үүний зэрэгцээ дижитал хөтлөгч, мэдлэгийн газрын зураг зэрэг хэрэглээ кампусын үйл ажиллагаанд шинэ эрч өгч, мэдээлэл дамжуулах, арга хэмжээ зохион байгуулах үр дүнг сайжруулсан. Дижитал болгох явцад их дээд сургуулиуд технологи, сэтгэл хөдлөлийг нэгтгэх арга замыг эрэлхийлж, дижитал технологийн давуу талыг ашиглахын зэрэгцээ өгөгдөл хүн хоорондын нүүр тулсан харилцааг орлохоос сэргийлж байна. Технологийн арга хэрэгсэл, халамжийн сэтгэлийг органик байдлаар нэгтгэсэн цагт л дижитал удирдлага үнэхээр оюутны өсөлтөд үйлчилнэ."}, {"zh": "问：关于智慧校园平台，下列哪一项正确？", "mn": "Асуулт: Ухаалаг кампусын платформын талаар доор дурдсанаас аль нь зөв бэ?"}]}'::jsonb),
('M62602','listening',2,10,'choice','','[{"key": "A", "text": "强迫学生进入食堂消费"}, {"key": "B", "text": "实时掌握学生整体状态"}, {"key": "C", "text": "统计学生课外活动时间"}, {"key": "D", "text": "取消了学生的借书限制"}]'::jsonb,'B','auto',1,'/mock-tests/m62602/listening.mp3',null,false,array['sk.listening.choice','voc.hsk6','hsk30']::text[],'«Оюутны хөрөг» нь өгөгдөл цуглуулж «оюутны сургууль дахь ерөнхий байдлыг бодит цагт мэддэг». Хариу B.',385.64,554.88,'随着信息技术的飞速发展，“云端管理”已逐渐融入高校日常管理的方方面面。许多学校通过建设智慧校园平台，实现学生事务“一站式”在线办理。这种以数字化为支撑的管理方式，不仅显著提升了办事效率，也推动了高校管理理念的转变。
以部分高校推出的“学生画像”系统为例，学校通过汇集学生的学习表现、借书记录、食堂消费等数据，实时了解学生在校的整体状态。借助数据分析，学校能够精准识别出生活困难或情绪焦虑的学生，并及时给予关怀。这一机制改变了以往问题出现后再处理的被动局面，使学生管理逐步转向主动服务。
与此同时，数字人主播、知识地图等应用不断为校园活动注入新动力，提升了信息传递和活动组织的效果。在推进数字化建设的过程中，高校也在探索技术与情感融合的方式，既发挥数字技术的优势，又避免让数据取代人与人之间面对面的沟通。只有将技术手段与关爱精神有机融合，数字化管理才能真正服务学生成长。
